<?php
namespace Tests\Feature;
use App\Models\User;
use Illuminate\Support\Facades\{DB,Hash};
use Laravel\Sanctum\Sanctum;
class SuperAdminCreationTest extends ProjectReviewRegressionTest {
 private function actor(string $role):User{return User::create(['first_name'=>'Test','last_name'=>'Actor','email'=>uniqid().'@example.test','password'=>'fixture-password','role'=>$role,'is_active'=>true]);}
 private function payload():array{return ['first_name'=>'New','last_name'=>'Super Admin','email'=>'new-super@example.test','password'=>'Temporary-12345','role'=>'super_admin','contact_number'=>'09617376781'];}
 public function test_super_admin_can_create_and_list_another_super_admin():void{$actor=$this->actor('super_admin');Sanctum::actingAs($actor);$p=$this->payload();$id=$this->postJson('/api/superadmin/users',$p)->assertCreated()->assertJsonPath('data.role','super_admin')->json('data.id');$u=User::findOrFail($id);$this->assertTrue(Hash::check($p['password'],$u->password));$this->assertTrue((bool)$u->must_change_password);$this->assertTrue((bool)$u->is_active);$this->getJson('/api/superadmin/users')->assertOk()->assertJsonFragment(['email'=>$p['email'],'role'=>'super_admin']);$this->getJson('/api/superadmin/users/'.$id)->assertOk();$audit=DB::table('audit_events')->where('event','account.created')->first();$this->assertEquals($actor->id,$audit->actor_id);$this->assertStringNotContainsString($p['password'],json_encode($audit));}
 public function test_other_roles_cannot_create_super_admin():void{foreach(['admin','faculty','student'] as $role){Sanctum::actingAs($this->actor($role));$this->postJson('/api/superadmin/users',$this->payload())->assertForbidden();}$this->assertDatabaseMissing('users',['email'=>'new-super@example.test']);}
 public function test_super_admin_password_requires_twelve_characters():void{Sanctum::actingAs($this->actor('super_admin'));$this->postJson('/api/superadmin/users',array_merge($this->payload(),['password'=>'shortpass']))->assertUnprocessable()->assertJsonValidationErrors('password');$this->assertDatabaseMissing('users',['email'=>'new-super@example.test']);}
 public function test_duplicate_email_cannot_create_second_account():void{Sanctum::actingAs($this->actor('super_admin'));$this->postJson('/api/superadmin/users',$this->payload())->assertCreated();$this->postJson('/api/superadmin/users',$this->payload())->assertUnprocessable()->assertJsonValidationErrors('email');$this->assertEquals(1,User::where('email','new-super@example.test')->count());}
 public function test_existing_super_admin_remains_protected():void{$actor=$this->actor('super_admin');$target=$this->actor('super_admin');Sanctum::actingAs($actor);$this->putJson('/api/superadmin/users/'.$target->id,['role'=>'faculty'])->assertForbidden();$this->deleteJson('/api/superadmin/users/'.$target->id)->assertForbidden();$this->patchJson('/api/superadmin/users/'.$target->id.'/toggle')->assertForbidden();$this->assertSame('super_admin',$target->fresh()->role);$this->assertTrue((bool)$target->fresh()->is_active);}
}
